/* VORVAN Live Guide — first-party client, no telemetry, cookies or storage.
 * Answers are generated by a free rules-based hosted service, not an external LLM. */
(()=>{
"use strict";
const root=document.getElementById("vv-assistant");
if(!root)return;
const endpoint="https://kukfpsqujlutlgwndplh.supabase.co/functions/v1/site-assistant";
const $=(selector)=>root.querySelector(selector);
const launch=$('[data-guide-launch]'),popup=$('[data-guide-panel]'),close=$('[data-guide-close]'),feed=$('[data-guide-feed]'),field=$('[data-guide-input]'),send=$('[data-guide-send]'),lang=$('[data-guide-language]');
const labels={
 en:{hi:"Welcome! I'm VORVAN's guided website assistant. How can I help?",fallback:"The live guide is temporarily unavailable. Please email info@vorvan.co.in.",privacy:"Please remove phone numbers, PAN/Aadhaar, email addresses and other personal data before sending.",topics:{partnership:"LSP partnership",api:"Lending API",credit:"Credit app",support:"Support",legal:"Legal",contact:"Emails"}},
 bn:{hi:"স্বাগতম! আমি VORVAN-এর তথ্য সহায়ক। কী জানতে চান?",fallback:"লাইভ গাইড এখন কাজ করছে না। info@vorvan.co.in-এ ইমেইল করুন।",privacy:"ফোন নম্বর, PAN/Aadhaar, ইমেইল বা ব্যক্তিগত তথ্য লিখবেন না।",topics:{partnership:"LSP পার্টনারশিপ",api:"লোন API",credit:"ক্রেডিট অ্যাপ",support:"সাপোর্ট",legal:"লিগ্যাল",contact:"ইমেইল"}},
 hi:{hi:"नमस्ते! मैं VORVAN का वेबसाइट जानकारी सहायक हूँ। क्या जानना चाहेंगे?",fallback:"लाइव गाइड उपलब्ध नहीं है। info@vorvan.co.in पर लिखें।",privacy:"कृपया फ़ोन, PAN/Aadhaar, ईमेल या निजी जानकारी न भेजें।",topics:{partnership:"LSP साझेदारी",api:"लोन API",credit:"क्रेडिट ऐप",support:"सहायता",legal:"कानूनी",contact:"ईमेल"}}
};
let busy=false;
function add(text,mine=false){const p=document.createElement("div");p.className="vv-msg"+(mine?" visitor":"");p.textContent=text;feed.append(p);feed.scrollTop=feed.scrollHeight}
function greeting(){feed.replaceChildren();add(labels[lang.value].hi)}
function open(opened){popup.hidden=!opened;launch.setAttribute("aria-expanded",String(opened));if(opened){field.focus()}else launch.focus()}
launch.addEventListener("click",()=>open(popup.hidden));close.addEventListener("click",()=>open(false));
document.addEventListener("keydown",(e)=>{if(e.key==="Escape"&&!popup.hidden)open(false)});
function looksSensitive(text){return /(?:\d[\s-]?){8,}|[^\s@]+@[^\s@]+\.[^\s@]+/.test(text)}
async function ask(topic,message){
 if(busy)return;const language=lang.value;const local=labels[language];
 if(message&&looksSensitive(message)){add(local.privacy);return}
 busy=true;send.disabled=true;
 const data={language};if(topic)data.topic=topic;if(message)data.message=message;
 try{
  const r=await fetch(endpoint,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(data),cache:"no-store",credentials:"omit",referrerPolicy:"no-referrer",signal:AbortSignal.timeout(8500)});
  const body=await r.json();
  if(!r.ok||typeof body.reply!=="string")throw Error("unavailable");
  add(body.reply);
 }catch{add(local.fallback)}
 finally{busy=false;send.disabled=false}
}
for(const b of root.querySelectorAll("[data-guide-topic]"))b.addEventListener("click",()=>{const t=b.getAttribute("data-guide-topic");add(labels[lang.value].topics[t]||t,true);ask(t,null)});
function sendMessage(){const text=field.value.trim();if(!text||text.length>240||busy)return;field.value="";add(text,true);ask(null,text)}
send.addEventListener("click",sendMessage);
field.addEventListener("keydown",(e)=>{if(e.key==="Enter"){e.preventDefault();sendMessage()}});
// Search bar in the hero opens the same free, live assistant with the visitor's question.
const quick=document.querySelector("[data-vv-search]");
const quickButton=document.querySelector("[data-vv-search-submit]");
function quickAsk(){
 if(!quick||!popup||busy)return;
 const question=quick.value.trim();
 if(!question)return;
 if(question.length>240){add(labels[lang.value].privacy);return}
 open(true);
 quick.value="";
 field.value=question;
 sendMessage();
}
if(quick&&quickButton){
 quickButton.addEventListener("click",quickAsk);
 quick.addEventListener("keydown",event=>{if(event.key==="Enter"){event.preventDefault();quickAsk()}});
}
lang.addEventListener("change",greeting);greeting();
})();
